--- Ряды метрик кэша: обращения за значением по итогу и длительность
--- чтения драйвером.
---
--- Промах кэша — не отказ: вызывающий пересчитает значение и никуда
--- об этом не напишет. Но доля промахов, выросшая за ночь, — это срок,
--- который кончается раньше, чем значение успевают спросить, или ключ,
--- в который попала метка времени; а отказ драйвера на чтении виден
--- только записью журнала, где подряд идущие повторы подавлены. Поэтому
--- итог каждого обращения — три слова: попадание, промах, отказ.
---
--- Обращение считается один раз, по первому чтению: повторное чтение под
--- замком и опрос ожидающих — часть того же обращения, и счёт каждого
--- опроса раздувал бы промахи ровно тогда, когда замок делает своё дело.
--- Запись в ряды не идёт: её отказ бросает и виден вызывающему.
---
--- Хранилище в метке — по имени (`name` в настройках, по умолчанию имя
--- драйвера), а не по приставке: приставка бывает пустой и бывает
--- собрана из имени узла, а имя называет тот, кто хранилище заводит.

local series = require('tnt.metrics.series')

local Module = {}

--- Сколько разных хранилищ видно в рядах: хранилища заводит код,
--- и больше сотни на узле — уже ошибка в коде.
Module.STORES = 100

--- Итоги обращения.
Module.HIT = 'hit'
Module.MISS = 'miss'
Module.FAILED = 'failed'

--- Корзины длительности, секунды: от 100 мкс до секунды — чтение
--- в памяти процесса идёт микросекунды, по сети до Redis — около
--- миллисекунды, а чтение дольше секунды — уже поломка кэша.
Module.BUCKETS = { 0.0001, 0.0005, 0.001, 0.0025, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1 }

local requests = series.counter('cache_requests_total', {
    help = 'Сколько обращений к кэшу за значением: по хранилищу и итогу — попадание, промах, отказ',
    labels = { store = Module.STORES, outcome = { Module.HIT, Module.MISS, Module.FAILED } },
})

local durations = series.histogram('cache_request_duration_seconds', {
    help = 'Сколько шло обращение к кэшу за значением: чтение драйвером',
    labels = { store = Module.STORES },
    buckets = Module.BUCKETS,
})

--- Считает обращение по итогу и кладёт его длительность.
---@param store string Имя хранилища
---@param outcome string `hit`, `miss` либо `failed`
---@param elapsed number Секунды по монотонным часам
function Module.asked(store, outcome, elapsed)
    requests:inc(1, { store = store, outcome = outcome })
    durations:observe(elapsed, { store = store })
end

return Module
